from lib import *
S = SS('x104')
steps = [
    step("BCrypt 的 strength 与耗时。BCryptPasswordEncoder 默认 strength=10;同一个密码 secret 编码两次得到两个不同的哈希($2a$10$2zXk… 和 $2a$10$j7Mp…,长度都是 60),因为每次随机加盐,两个都能 matches 回 true。strength 每加 2,编码耗时变成约 4 倍:strength 4 是 1.2 ms,6 是 4.8 ms,8 是 17.7 ms,10 是 70.1 ms,12 是 274.6 ms,14 是 1105.2 ms;matches 的耗时和 encode 几乎一样。取值范围:strength 3 和 32 都抛 IllegalArgumentException: Bad strength。strength 每加 1 就翻一倍,所以升级成本很容易失控:登录接口在 strength 12 时每次校验(matches 中位 282.3 ms)要用掉约 280 ms 的 CPU。", t=tl(S(1)), mark=lidx(S(1), 'strength=12', 'strength=14', 'Bad strength'), done=lidx(S(1), '默认 strength = 10', 'strength= 4', 'strength= 6', 'strength= 8', 'strength=10'), b=bars([['strength 4(ms)', 1.2, '1.2'], ['strength 8(ms)', 17.7, '17.7'], ['strength 10(ms)', 70.1, '70.1'], ['strength 12(ms)', 274.6, '274.6'], ['strength 14(ms)', 1105.2, '1105.2']], 1105.2, done=[0, 1, 2], mark=[3, 4]), kv=KV([['默认', 'strength 10,约 70 ms,哈希 60 字符'], ['每加 2', '耗时约 ×4'], ['盐', '每次随机,同一密码两次哈希不同'], ['取值', '4 到 31,超出抛 Bad strength']], ['每加 2'])),
    step("DelegatingPasswordEncoder(PasswordEncoderFactories.createDelegatingPasswordEncoder())。encode(\"secret\") 得到 {bcrypt}$2a$10$ABga…,前面带算法前缀。同一个明文对不同前缀的哈希都能 matches:{noop}(长度 12)、{bcrypt}(68)、{pbkdf2@SpringSecurity_v5_8}(124)、{scrypt@SpringSecurity_v5_8}(105)、{argon2@SpringSecurity_v5_8}(125),都是 true。没有前缀的哈希(比如直接从旧库里读出来的一个 BCrypt)会抛 IllegalArgumentException: Given that there is no default password encoder configured, each password must have a password encoding prefix. Please either prefix this password with '{noop}' or set a default password encoder in `DelegatingPasswordEncoder`.;调用 setDefaultPasswordEncoderForMatches(new BCryptPasswordEncoder()) 之后 matches 变成 true。upgradeEncoding(是否需要重新编码):{bcrypt} strength 4 是 true;strength 10(默认)和 strength 12 都是 false;{noop} 是 true——用它可以在用户登录成功时把旧哈希悄悄升级成新参数。", t=tl(S(2)), mark=lidx(S(2), '没有前缀的哈希', 'upgradeEncoding'), done=lidx(S(2), 'encode("secret")', '{noop}', '{argon2@', 'setDefaultPasswordEncoderForMatches'), b=bars([['支持的前缀个数(本篇测过的)', 5, '5'], ['{bcrypt} 哈希的长度', 68, '68'], ['{argon2@…} 哈希的长度', 125, '125']], 125, done=[0], mark=[1, 2]), kv=KV([['前缀', '{id}哈希,matches 按 id 选编码器'], ['没有前缀', '抛异常,要 setDefaultPasswordEncoderForMatches'], ['upgradeEncoding', 'strength 低于默认、{noop} 返回 true'], ['用途', '登录成功时顺手升级旧哈希']], ['前缀'])),
    step("边界。Spring Security 7 里 BCrypt 的 72 字节限制:encode 73 字节的密码抛 IllegalArgumentException: password cannot be more than 72 bytes;但 matches 并不拒绝更长的输入——一个 72 字节的密码编码出的哈希,拿一个前 72 字节相同、后面不同、总共 86 字节的密码去 matches 同样返回 true(超出的部分被忽略)。matches(null, 哈希) 没有抛异常。空密码:encode(\"\") 可以得到哈希,但 matches(\"\", 那个哈希) 返回 false。matches(\"secret\", \"not-a-hash\") 返回 false,不抛异常。", t=tl(S(3)), mark=lidx(S(3), '73 字节', '只在第 72 个字节之后不同', 'matches(\"\"'), done=lidx(S(3), 'matches(null', 'not-a-hash'), b=bars([['encode 73 字节的密码:是否抛异常(1=是)', 1, '是'], ['86 字节、前 72 字节相同的密码 matches 72 字节哈希(1=true)', 1, 'true'], ['matches(空密码, 空密码的哈希)(1=true)', 0, 'false']], 1, mark=[0, 1, 2]), kv=KV([['encode', '超过 72 字节会拒绝'], ['matches', '前 72 字节相同就通过,后面的字节被忽略'], ['空密码', 'encode 可以,matches 返回 false'], ['乱格式哈希', 'matches 返回 false,不抛异常']], ['matches'])),
    step("几种算法的默认参数(各取 5 次中位数,同一台机器)。BCrypt 默认(strength 10):encode 67.8 ms,matches 67.6 ms,哈希 60 字符。Pbkdf2 defaultsForSpringSecurity_v5_8:encode 38.8 ms,matches 38.9 ms,哈希 96 字符。SCrypt defaultsForSpringSecurity_v5_8:encode 112.5 ms,matches 106.3 ms,哈希 77 字符。Argon2 defaultsForSpringSecurity_v5_8:encode 16.6 ms,matches 15.5 ms,哈希 97 字符(需要 BouncyCastle)。四种算法都花了几十毫秒的量级,但它们之间并不是同等强度:默认参数下耗时只说明这台机器上的成本,比较抗破解能力要看各自的内存与并行度参数,本篇没有评估。", t=tl(S(4)), mark=lidx(S(4), 'Argon2'), done=lidx(S(4), 'BCrypt 默认', 'Pbkdf2', 'SCrypt'), b=bars([['BCrypt 默认 encode(ms)', 67.8, '67.8'], ['Pbkdf2 encode(ms)', 38.8, '38.8'], ['SCrypt encode(ms)', 112.5, '112.5'], ['Argon2 encode(ms)', 16.6, '16.6']], 112.5, done=[0, 1, 2], mark=[3]), kv=KV([['BCrypt', '67.8 ms,60 字符'], ['Pbkdf2', '38.8 ms,96 字符'], ['SCrypt', '112.5 ms,77 字符'], ['Argon2', '16.6 ms,97 字符,要 BouncyCastle']], ['Argon2'])),
]
